datasource db {
  provider = "sqlite"
  // Wasp requires that the url is set to the DATABASE_URL environment variable.
  url      = env("DATABASE_URL")
}

// Wasp requires the `prisma-client-js` generator to be present.
generator client {
  provider = "prisma-client-js"
}

model User {
  id       Int      @id @default(autoincrement())
  username String   @unique
  password String
  apiKeys  ApiKey[]
}

model ApiKey {
  id        Int      @id @default(autoincrement())
  key       String   @unique
  name      String
  quota     Int
  usage     Int      @default(0)
  userId    Int
  user      User     @relation(fields: [userId], references: [id])
  logs      ApiLog[]
  createdAt DateTime @default(now())
}

model ApiLog {
  id        Int      @id @default(autoincrement())
  endpoint  String
  status    Int
  apiKeyId  Int
  apiKey    ApiKey   @relation(fields: [apiKeyId], references: [id], onDelete: Cascade)
  timestamp DateTime @default(now())
}

import { app, page, route, query, action, api } from "@wasp.sh/spec";
import { MainPage } from "./src/MainPage" with { type: "ref" };
import { LoginPage } from "./src/LoginPage" with { type: "ref" };
import { SignupPage } from "./src/SignupPage" with { type: "ref" };
import { userSignupFields } from "./src/auth" with { type: "ref" };
import { getApiKeys } from "./src/queries" with { type: "ref" };
import { createApiKey, deleteApiKey } from "./src/actions" with { type: "ref" };
import { apiRequestHandler } from "./src/apis" with { type: "ref" };
import { devSeedSimple } from "./src/seeds" with { type: "ref" };

export default app({
  name: "app",
  title: "API Key Management Portal",
  wasp: { version: "^0.24.0" },
  head: ["<link rel='icon' href='/favicon.ico' />"],
  auth: {
    userEntity: "User",
    methods: {
      usernameAndPassword: {
        userSignupFields,
      },
    },
    onAuthFailedRedirectTo: "/login",
  },
  db: {
    seeds: [devSeedSimple],
  },
  spec: [
    route("RootRoute", "/", page(MainPage, { authRequired: true })),
    route("LoginRoute", "/login", page(LoginPage)),
    route("SignupRoute", "/signup", page(SignupPage)),
    query(getApiKeys, { entities: ["ApiKey", "ApiLog"] }),
    action(createApiKey, { entities: ["ApiKey"] }),
    action(deleteApiKey, { entities: ["ApiKey", "ApiLog"] }),
    api("GET", "/api/request", apiRequestHandler, { entities: ["ApiKey", "ApiLog"], auth: false }),
  ],
});

import { defineUserSignupFields } from 'wasp/server/auth';

export const userSignupFields = defineUserSignupFields({
  username: async (data: any) => {
    if (!data.username) {
      throw new Error('Username is required');
    }
    return data.username;
  },
  password: async (data: any) => {
    if (!data.password) {
      throw new Error('Password is required');
    }
    return data.password;
  }
});

import { sanitizeAndSerializeProviderData } from 'wasp/server/auth';

export const devSeedSimple = async (prisma: any) => {
  const existingUser = await prisma.user.findFirst({
    where: { username: 'devuser' }
  });
  if (existingUser) {
    return;
  }

  const providerData = await sanitizeAndSerializeProviderData({
    hashedPassword: 'password123',
  });

  await prisma.user.create({
    data: {
      username: 'devuser',
      password: 'password123',
      auth: {
        create: {
          identities: {
            create: {
              providerName: 'username',
              providerUserId: 'devuser',
              providerData: providerData,
            },
          },
        },
      },
    },
  });
};

